CREATE TABLE "bundles" ("id" UUID NOT NULL,"creator_id" UUID NOT NULL,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"cover_url" TEXT,"price" DECIMAL(10,2) NOT NULL,"status" "ProductStatus" NOT NULL DEFAULT 'DRAFT',"visibility" "ProductVisibility" NOT NULL DEFAULT 'PRIVATE',"published_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "bundles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bundle_items" ("bundle_id" UUID NOT NULL,"product_id" UUID NOT NULL,"sort_order" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "bundle_items_pkey" PRIMARY KEY ("bundle_id","product_id"));
CREATE TABLE "follows" ("id" UUID NOT NULL,"user_id" UUID NOT NULL,"creator_id" UUID,"subject_id" INTEGER,"grade_id" INTEGER,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "follows_pkey" PRIMARY KEY ("id"));
CREATE TABLE "referral_codes" ("id" UUID NOT NULL,"creator_id" UUID NOT NULL,"code" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "referral_codes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "referral_attributions" ("id" UUID NOT NULL,"referred_user_id" UUID NOT NULL,"referral_code_id" UUID NOT NULL,"expires_at" TIMESTAMP(3) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "referral_attributions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "referral_rewards" ("id" UUID NOT NULL,"attribution_id" UUID NOT NULL,"order_id" UUID NOT NULL,"creator_user_id" UUID NOT NULL,"amount" DECIMAL(10,2) NOT NULL,"revoked_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "referral_rewards_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "bundles_slug_key" ON "bundles"("slug"); CREATE INDEX "bundles_creator_id_status_idx" ON "bundles"("creator_id","status"); CREATE INDEX "follows_creator_id_idx" ON "follows"("creator_id"); CREATE UNIQUE INDEX "follows_user_id_creator_id_key" ON "follows"("user_id","creator_id"); CREATE UNIQUE INDEX "follows_user_id_subject_id_grade_id_key" ON "follows"("user_id","subject_id","grade_id"); CREATE UNIQUE INDEX "referral_codes_creator_id_key" ON "referral_codes"("creator_id"); CREATE UNIQUE INDEX "referral_codes_code_key" ON "referral_codes"("code"); CREATE UNIQUE INDEX "referral_attributions_referred_user_id_key" ON "referral_attributions"("referred_user_id"); CREATE UNIQUE INDEX "referral_rewards_order_id_key" ON "referral_rewards"("order_id"); CREATE INDEX "referral_rewards_creator_user_id_revoked_at_idx" ON "referral_rewards"("creator_user_id","revoked_at"); CREATE UNIQUE INDEX "cart_items_bundle_id_key" ON "cart_items"("bundle_id");
